-- Databricks notebook source
-- Incremental load: parquet files -> production.raw_events.orders
-- Bundle: orders_incremental_load v1.0.0 (pattern: incremental_load)
-- Generated by Databricks Agent. Do not edit by hand: change request.json and regenerate.

-- COMMAND ----------

-- Read the source and add lineage columns to every row.
CREATE OR REPLACE TEMPORARY VIEW source_raw AS
SELECT
  *,
  _metadata.file_path AS _source_file,
  current_timestamp() AS _ingested_at
FROM read_files(
  's3://prod-data-lake/events/orders/',
  format => 'parquet'
);

-- COMMAND ----------

-- Create the target on first run with the source schema (no-op afterwards).
CREATE TABLE IF NOT EXISTS production.raw_events.orders
CLUSTER BY (order_date)
AS SELECT * FROM source_raw LIMIT 0;

-- COMMAND ----------

-- Batch = rows at or after the current watermark. Using >= (not >) re-reads the boundary so
-- late rows sharing the max updated_at are not lost; the MERGE below makes that idempotent.
CREATE OR REPLACE TEMPORARY VIEW batch AS
SELECT *
FROM source_raw
WHERE (SELECT MAX(updated_at) FROM production.raw_events.orders) IS NULL
   OR updated_at >= (SELECT MAX(updated_at) FROM production.raw_events.orders);

-- COMMAND ----------

-- DQ: primary key (order_id) must not be NULL.
SELECT raise_error(concat('DQ check failed: NULL primary key (order_id) (', CAST(n AS STRING), ')'))
FROM (SELECT COUNT(*) AS n FROM batch WHERE order_id IS NULL)
WHERE n > 0;

-- DQ: required columns (customer_id, order_date) must not be NULL.
SELECT raise_error(concat('DQ check failed: NULL required columns (customer_id, order_date) (', CAST(n AS STRING), ')'))
FROM (SELECT COUNT(*) AS n FROM batch WHERE customer_id IS NULL OR order_date IS NULL)
WHERE n > 0;

-- COMMAND ----------

-- Keep only the latest version of each key within the batch.
CREATE OR REPLACE TEMPORARY VIEW batch_deduped AS
SELECT *
FROM batch
QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY updated_at DESC) = 1;

DECLARE OR REPLACE VARIABLE rows_loaded BIGINT DEFAULT 0;
SET VAR rows_loaded = (SELECT COUNT(*) FROM batch_deduped);

-- COMMAND ----------

-- Upsert. Only strictly newer source rows overwrite existing ones.
MERGE INTO production.raw_events.orders AS t
USING batch_deduped AS s
ON t.order_id = s.order_id
WHEN MATCHED AND s.updated_at > t.updated_at THEN UPDATE SET *
WHEN NOT MATCHED THEN INSERT *;

-- COMMAND ----------

-- DQ: freshness. Fail if the newest row is older than the SLA.
SELECT raise_error('DQ check failed: production.raw_events.orders is staler than 26h')
FROM (SELECT MAX(updated_at) AS newest FROM production.raw_events.orders)
WHERE newest IS NULL OR newest < current_timestamp() - INTERVAL 26 HOURS;

-- COMMAND ----------

-- Audit: one row per successful run.
CREATE TABLE IF NOT EXISTS production.raw_events._load_audit (
  bundle_name STRING,
  bundle_version STRING,
  table_name STRING,
  loaded_at TIMESTAMP,
  rows_loaded BIGINT,
  status STRING
);

INSERT INTO production.raw_events._load_audit
VALUES ('orders_incremental_load', '1.0.0', 'production.raw_events.orders', current_timestamp(), rows_loaded, 'SUCCEEDED');
